"""Report completed frozen-training diagnostics without opening heldout or model labels."""
import pathlib,json,hashlib,datetime,csv
import numpy as np
ROOT=pathlib.Path(__file__).resolve().parents[1];OUT=ROOT/'outputs'
def sha(p):return hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
def main():
 names={'objective':'training_objective_audit_v2','balanced':'reference_control_audit_v2','normalizer':'normalizer_control_audit_v1','em':'em_switch_audit_v2'}
 packs={k:json.loads((OUT/v/'summary.json').read_text()) for k,v in names.items()};assert all(len(p['records'])==2 for p in packs.values())
 dest=OUT/'training_audit_report_v1';assert not dest.exists();dest.mkdir()
 table='| Seed | Full-bank total dL/dalpha | Balanced batch32 total | EM full-bank partial | EM balanced batch32 partial | EM gradient discrepancy |\n|---|---:|---:|---:|---:|---:|\n'
 normal='| Seed | Estimator | Mean dL/dalpha | Batch SD | IID MC SE when applicable |\n|---|---|---:|---:|---:|\n';rows=[]
 for seed in [0,1]:
  run=f'rp_linear_small_seed{seed}';ob=next(r for r in packs['objective']['records'] if r['run']==run);bal=next(r for r in packs['balanced']['records'] if r['run']==run);nr=next(r for r in packs['normalizer']['records'] if r['run']==run);em=next(r for r in packs['em']['records'] if r['run']==run);t=next(m for m in em['modes'] if m['em'])
  assert all(r['heldout_read'] is False and r['latent_truth_read'] is False and r['optimizer_updates']==0 and r['checkpoint_unchanged'] for r in [ob,bal,nr,em])
  table+=f"|{seed}|{bal['full_native_alpha_derivative']:.6f}|{bal['balanced_batch_reference_alpha_derivative']:.6f}|{t['full_alpha_derivative']:.6f}|{t['balanced_batch_alpha_derivative']:.6f}|{t['balanced_batch_vs_full_gradient_max_abs_error']:.3g}|\n"
  for s in nr['estimates']:
   se='not iid' if s['iid_MC_SE'] is None else f"{s['iid_MC_SE']:.6f}";normal+=f"|{seed}|{s['estimator']}|{s['alpha_derivative_mean']:.6f}|{s['std_over_batches']:.6f}|{se}|\n";rows.append({'seed':seed,'full_bank_alpha_derivative':nr['full_bank_alpha_derivative'],**s})
  with np.load(nr['raw_estimates']) as ar:values=ar['estimator_values']
  np.savetxt(dest/(run+'_normalizer_estimates.csv'),values,delimiter=',',header=','.join(s['estimator'] for s in nr['estimates']),comments='',fmt='%.17g')
 text=('# Training-only reference and EM-contract audit\n\nAll quantities below use two completed native default checkpoints on the small task and training observations only. No true-state labels, heldout observations, optimizer updates or model-selection changes were used. The original12 fitting protocol remains intact, and four matched existing-source EM-option learning controls are separately declared before heldout scoring.\n\n'+table+'\nThe same frozen parameters give opposite total-derivative directions when the target batch is also the reference bank. Equal target frequencies rule out target-averaging noise for the balanced control. The per-target decomposition matches the native loss and A gradient, and the balanced full-reference average matches the full gradient to numerical precision.\n\n'+normal+'\nDropping only the designated diagonal or using independent references reverses the scalar direction at these frozen points, but neither is demonstrated to recover the exact full-bank gradient or improve a trained model. The oracle-normalizer estimator has large conditional MC variance; its observed mean deviation is not evidence of systematic bias given its reported SE. The two running-normalizer adaptations do not recover the full-bank derivative here. They are fixed-parameter controls, not an official SogCLR reproduction or a test of its convergence while model parameters change. All1,024 recorded batch estimates per model are exported as CSV; caches and raw array hashes remain on the server.\n\n'+'A simpler source-provided control is decisive for the derivative attribution: `em=True` holds the inferred posterior fixed in the M-step. It leaves the forward loss value unchanged while changing a total derivative into a partial derivative. At these points, the A-gradient reference dependence disappears. An independently held-posterior M-step matches that partial derivative. Central finite differences near the covariance boundary require step halving; the original h=1e-5 failure and the full convergence grid are retained. A finite difference that recomputes the posterior would test the wrong derivative contract.\n\n'+'This is not proof of calibrated dynamics or of a new world-model gap. The encoder can still depend on the reference construction, and the Gaussian auxiliary approximation remains distinct from proper RPM likelihood. The already-provided EM option must be tested through matched complete learning before any new mechanism is designed. The added four fits preserve model, data, initial parameter arrays, batch RNG, Adam, stabilization and10,000-update terminal budget. All16 models/maps will be frozen before the first heldout comparison.\n\n'+'Current research judgment: reject the argument that the observed default A-gradient effect alone requires a new architecture. Retain a narrower unresolved question about how inference/optimization contracts affect reusable dynamics learning. Forecast consequences, uncertainty calibration, independent-data/generalization evidence and a useful method advantage remain unproven. Accepted final research directions:0.\n\nSee `LITERATURE_REFERENCE_BOUNDARY54_V1.md` for existing gradient-bias, normalization, nonlinear system-identification and negative-sampling work. The known components are not renamed as an invention.\n')
 (ROOT/'TRAINING_OBJECTIVE_FINDING54_V1.md').write_text(text,encoding='utf-8')
 summary={'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'status':'COMPLETE_TRAIN_ONLY_REFERENCE_AND_EXISTING_EM_OPTION_ATTRIBUTION','source_summaries':{k:sha(OUT/v/'summary.json') for k,v in names.items()},'finding_sha256':sha(ROOT/'TRAINING_OBJECTIVE_FINDING54_V1.md'),'normalizer_estimates':rows,'accepted_directions':0,'formal_heldout_results_used':False,'scientific_decision':'Default total-derivative A-reference sensitivity has an existing native fixed-posterior counter-control. No new world-model primitive established. Matched learning control pending.'}
 (dest/'summary.json').write_text(json.dumps(summary,indent=2),encoding='utf-8');print(json.dumps({'status':summary['status'],'finding_sha256':summary['finding_sha256'],'accepted_directions':0}),flush=True)
if __name__=='__main__':main()
